INSERT INTO `announcements` VALUES (1,'[INFORMASI AKADEMIS] Jadwal Pelaksanaan Ujian Tengah Semester (UTS) Berbasis Computer Based Test (CBT)','Kepada Yth. Seluruh Siswa/I Kelas X, XI, dan XII SMKN 1 CIBINONG,\n\nDiberitahukan bahwa pelaksanaan Ujian Tengah Semester (UTS) Semester Ganjil TA 2026/2027 secara daring melalui portal E-Learning SMKN 1 CIBINONG akan dilaksanakan mulai:\n\nTanggal: 19 – 23 Oktober 2026\n\nAkses Portal: Melalui menu Ujian CBT Online pada E-Learning\n\nKetentuan Wajib:\n\nPastikan akun E-Learning Anda dapat diakses dengan baik dan kartu ujian telah diverifikasi oleh wali kelas.\n\nPengerjaan ujian dilakukan sesuai dengan jadwal jam mata pelajaran yang tertera di aplikasi.\n\nApabila mengalami kendala teknis saat pengerjaan soal, segera hubungi Proktor/Tim IT di ruang laboratorium.\n\nSelamat mempersiapkan diri dan jaga selalu integritas serta kejujuran dalam berujian.\n\nCibinong, 12 Oktober 2026\n\nKurikulum & TIM IT SMKN 1 CIBINON','all',3,NULL,1,'2026-09-21 23:56:15','2026-09-21 23:56:15'),(2,'RAPAT GTK','Untuk semua para GTK diharap berkumpul pada jam 09.00 wib di AULA 1','guru',3,NULL,1,'2026-09-21 23:58:08','2026-09-21 23:58:08');
/*!40000 ALTER TABLE `announcements` ENABLE KEYS */;
UNLOCK TABLES;

