INSERT INTO `course_materials` VALUES (1,8,'Modul 1 - Instalasi Prometheus','video','https://youtu.be/M6ds-70GIpY?si=9NLIZUVWNBAWPOSk','Pelajari dan Pahami materi tersebut',1,3,'2026-09-21 07:05:51'),(2,8,'Modul 2 - Pengenalan Node Exporter','video','https://youtu.be/dQw4w9WgXcQ?si=NoBxJkxLc6dqHlV9','Rangkum materi tersebut dan pelajari',2,NULL,'2026-09-22 01:25:08'),(4,15,'Modul 1: Pengenalan Huruf Hiragana (46 Huruf Dasar)','text',NULL,'Huruf Hiragana adalah sistem alfabet fonetik Jepang yang digunakan untuk kata-kata asli Jepang dan partikel gramatikal.\n\n1. Huruf Vokal Dasar:\n- あ (a), い (i), う (u), え (e), お (o)\n\n2. Baris K, S, T, N, H, M, Y, R, W, N:\n- か (ka), き (ki), く (ku), け (ke), こ (ko)\n- さ (sa), し (shi), す (su), せ (se), そ (so)\n- た (ta), ち (chi), つ (tsu), て (te), と (to)\n- な (na), に (ni), ぬ (nu), ね (ne), の (no)\n- は (ha), ひ (hi), ふ (fu), へ (he), ほ (ho)\n- ま (ma), み (mi), む (mu), め (me), も (mo)\n- や (ya), ゆ (yu), よ (yo)\n- ら (ra), り (ri), る (ru), れ (re), ろ (ro)\n- わ (wa), を (wo), ん (n)\n\nLatihan:\nTuliskan nama panggilan Anda dalam huruf Hiragana dan latih urutan goresan (hitsujun) yang benar.',1,3,'2026-11-10 04:04:22'),(5,15,'Modul 2: Ungkapan Salam Sehari-hari (Aisatsu) & Etika Membungkuk (Ojigi)','text',NULL,'Dalam kebudayaan Jepang, Aisatsu (salam) adalah dasar dari komunikasi dan pembentukan karakter sopan santun:\n\n1. Salam Waktu:\n- Pagi: おはようございます (Ohayou gozaimasu)\n- Siang / Umum: こんにちは (Konnichiwa)\n- Malam: こんばんは (Konbanwa)\n- Selamat Tidur: おやすみなさい (Oyasuminasai)\n\n2. Ucapan Terima Kasih & Maaf:\n- Terima kasih: ありがとうございます (Arigatou gozaimasu)\n- Maaf / Permisi: すみません (Sumimasen)\n\n3. Salam Berpisah:\n- Sampai jumpa: さようなら (Sayounara) / またあした (Mata ashita)\n\nEtika Ojigi:\n- Eshaku (15 derajat) untuk salam santai.\n- Keirei (30 derajat) untuk menghormati guru / atasan.\n- Saikeirei (45 derajat) untuk permohonan maaf mendalam atau rasa hormat tertinggi.',2,3,'2026-11-10 04:04:22'),(6,15,'Modul 3: Perkenalan Diri (Jikoshoukai) & Partikel Dasar は (wa) dan の (no)','text',NULL,'Struktur baku perkenalan diri:\n\n1. Pembuka: はじめまして (Hajimemashite - Senang berkenalan dengan Anda)\n2. Menyebutkan Nama: わたしは [Nama] です (Watashi wa [Nama] desu)\n3. Menyebutkan Status: わたしは SMKN 1 Cibinong の がくせい です (Watashi wa SMKN 1 Cibinong no gakusei desu)\n4. Penutup: どうぞよろしくおねがいします (Douzo yoroshiku onegaishimasu)\n\nPenjelasan Tata Bahasa:\n- Partikel は (dibaca \'wa\') berfungsi sebagai penanda subjek/topik kalimat.\n- Partikel の (no) berfungsi menghubungkan dua kata benda dan menyatakan kepemilikan/asal.\n- です (desu) adalah kopula penutup kalimat formal.',3,3,'2026-11-10 04:04:22'),(7,16,'Modul 1: Bilangan, Waktu (Jikan), dan Hari (Youbi)','text',NULL,'1. Hari dalam Bahasa Jepang (Youbi):\n- Senin: げつようび (Getsuyoubi)\n- Selasa: かようび (Kayoubi)\n- Rabu: すいようび (Suiyoubi)\n- Kamis: もくようび (Mokuyoubi)\n- Jumat: きんようび (Kinyoubi)\n- Sabtu: どようび (Doyoubi)\n- Minggu: にちようび (Nichiyoubi)\n\n2. Satuan Waktu:\n- Jam = ...じ (ji), Menit = ...ふん / ぷん (fun / pun)\nContoh: いま 8じ 30ぷん です (Ima hachi-ji sanjuppun desu = Sekarang jam 08.30).',1,3,'2026-11-10 04:04:22'),(8,16,'Modul 2: Kosakata Lingkungan Sekolah & Partikel Tempat で (de) dan Ke に (ni)','text',NULL,'1. Fasilitas Sekolah:\n- きょうしつ (Kyoushitsu = Ruang Kelas)\n- としょかん (Toshokan = Perpustakaan)\n- じむしつ (Jimushitsu = Kantor TU)\n- トイレ (Toire = Toilet)\n\n2. Penggunaan Partikel:\n- Partikel で (de): Menunjukkan tempat terjadinya suatu aktivitas.\n  Contoh: としょかんで べんきょうします (Toshokan de benkyou shimasu = Belajar di perpustakaan).\n- Partikel に (ni): Menunjukkan tujuan arah pergi / waktu tertentu.\n  Contoh: がっこうに いきます (Gakkou ni ikimasu = Pergi ke sekolah).',2,3,'2026-11-10 04:04:22'),(9,17,'Modul 1: Budaya Kerja Industri IT Jepang (5S & Kaizen)','text',NULL,'Budaya kerja perusahaan Jepang (Monodzukuri & IT Engineering):\n\n1. 5S Principles:\n- 整理 (Seiri): Ringkas / Memilah barang atau kode yang tidak diperlukan.\n- 整頓 (Seiton): Rapi / Menyusun repositori dan alat kerja pada tempatnya.\n- 清掃 (Seisou): Resik / Menjaga kebersihan lingkungan fisik & kebersihan sistem.\n- 清潔 (Seiketsu): Rawat / Mempertahankan standar kerja konsisten.\n- 躾 (Shitsuke): Rajin / Membentuk kedisiplinan dan kepatuhan SOP.\n\n2. Kaizen (改善):\nKonsep perbaikan berkelanjutan secara bertahap dalam pengembangan software, mirip dengan metodologi Agile / Continuous Improvement.',1,3,'2026-11-10 04:04:22'),(10,17,'Modul 2: Komunikasi Bisnis & Etika Email / Hou-Ren-So (報連相)','text',NULL,'Hou-Ren-So adalah pilar utama komunikasi tim kerja Jepang:\n1. 報告 (Houkoku): Melaporkan progress tugas atau pekerjaan secara berkala.\n2. 連絡 (Renraku): Menginformasikan fakta atau situasi terbaru kepada tim.\n3. 相談 (Soudan): Berkonsultasi sebelum mengambil keputusan krusial atau ketika menghadapi kendala teknis.',2,3,'2026-11-10 04:04:22'),(11,18,'Modul 1: Budaya Kerja Industri IT Jepang (5S & Kaizen)','text',NULL,'Budaya kerja perusahaan Jepang (Monodzukuri & IT Engineering):\n\n1. 5S Principles:\n- 整理 (Seiri): Ringkas / Memilah barang atau kode yang tidak diperlukan.\n- 整頓 (Seiton): Rapi / Menyusun repositori dan alat kerja pada tempatnya.\n- 清掃 (Seisou): Resik / Menjaga kebersihan lingkungan fisik & kebersihan sistem.\n- 清潔 (Seiketsu): Rawat / Mempertahankan standar kerja konsisten.\n- 躾 (Shitsuke): Rajin / Membentuk kedisiplinan dan kepatuhan SOP.\n\n2. Kaizen (改善):\nKonsep perbaikan berkelanjutan secara bertahap dalam pengembangan software, mirip dengan metodologi Agile / Continuous Improvement.',3,3,'2026-11-10 04:04:22'),(12,18,'Modul 2: Komunikasi Bisnis & Etika Email / Hou-Ren-So (報連相)','text',NULL,'Hou-Ren-So adalah pilar utama komunikasi tim kerja Jepang:\n1. 報告 (Houkoku): Melaporkan progress tugas atau pekerjaan secara berkala.\n2. 連絡 (Renraku): Menginformasikan fakta atau situasi terbaru kepada tim.\n3. 相談 (Soudan): Berkonsultasi sebelum mengambil keputusan krusial atau ketika menghadapi kendala teknis.',3,3,'2026-11-10 04:04:22'),(13,9,'Modul 1: Arsitektur CI/CD Pipeline & GitHub Actions','text',NULL,'CI/CD (Continuous Integration & Continuous Deployment) adalah pilar modern software delivery.\n- Continuous Integration: Otomasi proses build, linting, dan unit testing setiap developer melakukan push kode ke branch repositori.\n- Continuous Deployment: Otomasi rilis aplikasi langsung ke server staging atau production begitu tes CI lulus tanpa intervensi manual.\n- Contoh tools: GitHub Actions, GitLab CI, Jenkins, ArgoCD.',1,3,'2026-11-10 04:04:22'),(14,9,'Modul 2: Docker Containerization & Multi-stage Build','text',NULL,'Container vs Virtual Machine:\n- Container berbagi OS kernel host sehingga sangat ringan (lightweight) dan startup dalam hitungan detik.\n- Dockerfile: Blueprint pembuatan image. Gunakan multi-stage build untuk meminimalkan ukuran image akhir dan meningkatkan keamanan.\n- Docker Compose: Mendefinisikan konfigurasi multi-container (misal Web App + MySQL + Redis) dalam satu berkas yaml.',2,3,'2026-11-10 04:04:22'),(15,9,'Modul 3: Container Orchestration dengan Kubernetes (K8s)','text',NULL,'Komponen K8s:\n- Pod: Unit komputasi terkecil di K8s.\n- Deployment: Mengatur replikasi pod, rolling update, dan rollback otomatis.\n- Service: Mengekspos pod ke jaringan internal (ClusterIP) atau publik (NodePort / LoadBalancer).\n- Ingress: Mengatur routing HTTP/HTTPS berbasis host atau path URL.',3,3,'2026-11-10 04:04:22'),(16,19,'Modul 1: Arsitektur CI/CD Pipeline & GitHub Actions','text',NULL,'CI/CD (Continuous Integration & Continuous Deployment) adalah pilar modern software delivery.\n- Continuous Integration: Otomasi proses build, linting, dan unit testing setiap developer melakukan push kode ke branch repositori.\n- Continuous Deployment: Otomasi rilis aplikasi langsung ke server staging atau production begitu tes CI lulus tanpa intervensi manual.\n- Contoh tools: GitHub Actions, GitLab CI, Jenkins, ArgoCD.',4,3,'2026-11-10 04:04:22'),(17,19,'Modul 2: Docker Containerization & Multi-stage Build','text',NULL,'Container vs Virtual Machine:\n- Container berbagi OS kernel host sehingga sangat ringan (lightweight) dan startup dalam hitungan detik.\n- Dockerfile: Blueprint pembuatan image. Gunakan multi-stage build untuk meminimalkan ukuran image akhir dan meningkatkan keamanan.\n- Docker Compose: Mendefinisikan konfigurasi multi-container (misal Web App + MySQL + Redis) dalam satu berkas yaml.',4,3,'2026-11-10 04:04:22'),(18,19,'Modul 3: Container Orchestration dengan Kubernetes (K8s)','text',NULL,'Komponen K8s:\n- Pod: Unit komputasi terkecil di K8s.\n- Deployment: Mengatur replikasi pod, rolling update, dan rollback otomatis.\n- Service: Mengekspos pod ke jaringan internal (ClusterIP) atau publik (NodePort / LoadBalancer).\n- Ingress: Mengatur routing HTTP/HTTPS berbasis host atau path URL.',4,3,'2026-11-10 04:04:22'),(19,10,'Modul 1: Version Control Git & Perintah Dasar Kolaborasi','text',NULL,'Alur kerja Git lokal & remote:\n1. git init: Inisialisasi repositori baru.\n2. git add .: Menambahkan berkas ke staging area.\n3. git commit -m \'pesan\': Menyimpan snapshot perubahan.\n4. git branch feature-x: Membuat cabang pengembangan baru.\n5. git merge: Menggabungkan cabang fitur ke cabang utama (main).',1,3,'2026-11-10 04:04:22'),(20,10,'Modul 2: Otomasi Server Linux & SSH Key Authentication','text',NULL,'Akses remote server aman menggunakan SSH (Secure Shell):\n- Generate key pair: ssh-keygen -t ed25519\n- Menyalin public key ke server: ssh-copy-id user@ip_server\n- Menonaktifkan password authentication di /etc/ssh/sshd_config untuk keamanan ekstra.',2,3,'2026-11-10 04:04:22'),(21,11,'Modul 1: File Hierarchy Standard (FHS) Linux','text',NULL,'Struktur direktori pohon pada sistem operasi Linux:\n- / : Root direktori induk.\n- /etc : Berkas konfigurasi sistem dan layanan.\n- /home : Direktori kerja pengguna personal.\n- /var/log : Tempat penyimpanan log sistem dan aplikasi.\n- /bin & /usr/bin : Tempat binary executable perintah pengguna.',1,3,'2026-11-10 04:04:22'),(22,11,'Modul 2: Manajemen Hak Akses File (Permissions & Ownership)','text',NULL,'Izin file terdiri dari 3 segmen: User (u), Group (g), Other (o):\n- Read (r) = 4\n- Write (w) = 2\n- Execute (x) = 1\nContoh: chmod 755 script.sh artinya User memiliki rwx (7), Group rx (5), Other rx (5).\nPerintah chown user:group namafile digunakan untuk mengubah kepemilikan berkas.',2,3,'2026-11-10 04:04:22'),(23,12,'Modul 1: Fondasi Framework Flutter & Stateless vs Stateful Widget','text',NULL,'Flutter menggunakan bahasa pemrograman Dart untuk membangun UI deklaratif:\n- StatelessWidget: Widget statis yang tampilannya tidak bergantung pada perubahan data dinamis setelah dibuat.\n- StatefulWidget: Widget dinamis yang dapat memperbarui tampilan layar saat nilai variabel berubah melalui fungsi setState().',1,3,'2026-11-10 04:04:22'),(24,12,'Modul 2: Komunikasi Data dengan REST API & Async/Await Dart','text',NULL,'Mengambil data JSON dari web service:\n- Gunakan package \'http\' untuk request GET, POST, PUT, DELETE.\n- Model serialisasi: Konversi jsonDecode(response.body) menjadi objek Dart strongly typed.\n- Exception handling menggunakan blok try-catch untuk menangani koneksi timeout atau error 404/500.',2,3,'2026-11-10 04:04:22'),(25,20,'Modul 1: Fondasi Framework Flutter & Stateless vs Stateful Widget','text',NULL,'Flutter menggunakan bahasa pemrograman Dart untuk membangun UI deklaratif:\n- StatelessWidget: Widget statis yang tampilannya tidak bergantung pada perubahan data dinamis setelah dibuat.\n- StatefulWidget: Widget dinamis yang dapat memperbarui tampilan layar saat nilai variabel berubah melalui fungsi setState().',3,3,'2026-11-10 04:04:22'),(26,20,'Modul 2: Komunikasi Data dengan REST API & Async/Await Dart','text',NULL,'Mengambil data JSON dari web service:\n- Gunakan package \'http\' untuk request GET, POST, PUT, DELETE.\n- Model serialisasi: Konversi jsonDecode(response.body) menjadi objek Dart strongly typed.\n- Exception handling menggunakan blok try-catch untuk menangani koneksi timeout atau error 404/500.',3,3,'2026-11-10 04:04:22'),(27,13,'Modul 1: Tata Letak Modern dengan CSS Flexbox & CSS Grid','text',NULL,'Membangun tampilan responsif:\n- Flexbox: Ideal untuk tata letak satu dimensi (baris atau kolom). Properti utama: display: flex, justify-content, align-items, flex-wrap.\n- Grid: Ideal untuk tata letak dua dimensi (baris dan kolom bersamaan). Properti utama: display: grid, grid-template-columns, gap.',1,3,'2026-11-10 04:04:22'),(28,13,'Modul 2: Keamanan Backend PHP & PDO Prepared Statements','text',NULL,'Mencegah serangan SQL Injection:\n- JANGAN menggunakan string concatenation pada query database.\n- SELALU gunakan PDO (PHP Data Objects) dengan prepared statement dan bind parameter (e.g. SELECT * FROM users WHERE email = ?).',2,3,'2026-11-10 04:04:22'),(29,14,'Modul 1: Logika Pemrograman, Algoritma & Flowchart','text',NULL,'Algoritma adalah urutan logis langkah-langkah terstruktur untuk menyelesaikan suatu permasalahan:\n- Simbol Oval / Terminator: Menandai Start dan End.\n- Simbol Persegi Panjang / Process: Melakukan kalkulasi atau manipulasi data.\n- Simbol Belah Ketupat / Decision: Percabangan kondisi (Ya / Tidak).',1,3,'2026-11-10 04:04:22'),(30,14,'Modul 2: Struktur Percabangan dan Perulangan (Loops)','text',NULL,'Struktur kontrol alur program:\n1. Percabangan: if, else if, else, dan switch-case untuk mengevaluasi kondisi logika boolean (true/false).\n2. Perulangan: for loop (jumlah iterasi terdefinisi pasti), while loop (eksekusi selama kondisi terpenuhi), do-while (minimal 1x eksekusi).',2,3,'2026-11-10 04:04:22');
/*!40000 ALTER TABLE `course_materials` ENABLE KEYS */;
